  const partOverrides = Object.freeze({"pau-can-ex-4a1d7a5b14de49c1a545b0a194bd33fc":[{"id":"pau-can-ex-4a1d7a5b14de49c1a545b0a194bd33fc:whole","label":"","text":"Se sabe que la suma de tres números naturales es 22 y que la suma de cuatro veces el primero más el triple del segundo más el doble del tercero es 61. ¿Puede ser 15 uno de los tres números? En caso afirmativo, calcula los restantes. ¿Existen otras opciones?","semanticAnswer":"Sí: la única terna que contiene 15 es (1, 15, 6). Las otras opciones son (2,13,7), (3,11,8), (4,9,9), (5,7,10), (6,5,11), (7,3,12) y (8,1,13).","distractors":["Sí: (15,1,6), y no hay más opciones.","Sí: (1,6,15), y las demás ternas se obtienen permutando.","No puede aparecer 15 en ninguna terna de números naturales."],"distractorEvidence":["Coloca 15 en la primera posición y no verifica la ecuación ponderada.","Ignora que los coeficientes 4, 3 y 2 distinguen las posiciones.","Descarta la solución (1,15,6), que verifica ambas ecuaciones."],"solutionSteps":["Planteamos las dos condiciones: x+y+z=22 y 4x+3y+2z=61.","Restamos dos veces la primera ecuación a la segunda y obtenemos 2x+y=17; por tanto y=17−2x y z=x+5.","Para x,y,z naturales positivos debe cumplirse 1≤x≤8. Al probar esos ocho valores aparecen todas las ternas: (1,15,6), (2,13,7), (3,11,8), (4,9,9), (5,7,10), (6,5,11), (7,3,12) y (8,1,13).","Solo la primera contiene 15. Comprobación: 1+15+6=22 y 4·1+3·15+2·6=61."],"finalAnswer":"Sí: (1,15,6). Hay además otras siete ternas naturales positivas.","verification":{"verified":true,"method":"Parametrización entera y comprobación exhaustiva","detail":"y=17−2x, z=x+5 y 1≤x≤8 enumeran exactamente todas las soluciones naturales positivas."}}],"pau-can-ex-e10495ba33971cca4641d0fc6f1389aa":[{"id":"pau-can-ex-e10495ba33971cca4641d0fc6f1389aa:a","label":"a)","text":"Halla a y b sabiendo que f tiene extremos relativos en x=1 y en x=2.","semanticAnswer":"a=−2/3 y b=−1/6.","distractors":["a=2/3 y b=−1/6.","a=−2/3 y b=1/6.","a=−1/3 y b=−1/6."],"distractorEvidence":["Cambia el signo de a.","Cambia el signo de b.","Pierde el factor 2 al resolver el sistema."],"solutionSteps":["Derivamos: f′(x)=a/x+2bx+1.","Como hay extremos en x=1 y x=2, imponemos f′(1)=0 y f′(2)=0: a+2b+1=0 y a/2+4b+1=0.","Resolviendo el sistema se obtiene b=−1/6 y a=−2/3.","Comprobación: f′(1)=−2/3−1/3+1=0 y f′(2)=−1/3−2/3+1=0."],"finalAnswer":"a=−2/3, b=−1/6.","verification":{"verified":true,"method":"Sistema formado por las condiciones f′(1)=f′(2)=0"}},{"id":"pau-can-ex-e10495ba33971cca4641d0fc6f1389aa:b","label":"b)","text":"¿Qué tipo de extremos tiene f en x=1 y en x=2?","semanticAnswer":"En x=1 hay un mínimo relativo y en x=2 hay un máximo relativo.","distractors":["En x=1 hay un máximo y en x=2 un mínimo.","Los dos puntos son máximos relativos.","Los dos puntos son mínimos relativos."],"distractorEvidence":["Invierte los signos de f′′.","Ignora que f′′(1)>0.","Ignora que f′′(2)<0."],"solutionSteps":["Con a=−2/3 y b=−1/6, f′′(x)=2/(3x²)−1/3=(2−x²)/(3x²).","f′′(1)=1/3>0, luego en x=1 la gráfica es convexa y hay un mínimo relativo.","f′′(2)=−1/6<0, luego en x=2 la gráfica es cóncava y hay un máximo relativo.","La recta de signos de f′ confirma el cambio − a + en x=1 y + a − en x=2."],"finalAnswer":"Mínimo relativo en x=1 y máximo relativo en x=2.","verification":{"verified":true,"method":"Signo de la segunda derivada y cambio de signo de f′"}}],"pau-user-and-556322ecfdbde7e83340fc0f6727":[{"id":"pau-user-and-556322ecfdbde7e83340fc0f6727:a","label":"a)","text":"Determina los intervalos de crecimiento y de decrecimiento de f.","semanticAnswer":"Crece en (−3/2,1) y decrece en (−∞,−3/2) y (1,+∞).","distractors":["Crece en (−∞,−3/2) y (1,+∞).","Crece en (−3/2,+∞).","Decrece únicamente en (1,+∞)."],"distractorEvidence":["Invierte toda la tabla de signos.","Omite el cambio de signo en x=1.","Omite el tramo x<−3/2."],"solutionSteps":["Derivamos f(x)=(3x−2x²)eˣ: f′(x)=eˣ(3−x−2x²)=−eˣ(2x+3)(x−1).","Como eˣ>0, los ceros de f′ son x=−3/2 y x=1.","Recta de signos de f′: negativa en (−∞,−3/2), positiva en (−3/2,1) y negativa en (1,+∞).","Por tanto f decrece, luego crece y finalmente vuelve a decrecer en esos intervalos."],"finalAnswer":"Crece en (−3/2,1); decrece en (−∞,−3/2)∪(1,+∞).","verification":{"verified":true,"method":"Recta real de signos de f′"}},{"id":"pau-user-and-556322ecfdbde7e83340fc0f6727:b","label":"b)","text":"Calcula los extremos relativos de f (abscisas donde se obtienen y valores que se alcanzan).","semanticAnswer":"Mínimo relativo en (−3/2,−9e^(−3/2)) y máximo relativo en (1,e).","distractors":["Máximo en (−3/2,−9e^(−3/2)) y mínimo en (1,e).","Mínimo en (−3/2,9e^(−3/2)) y máximo en (1,e).","El único extremo relativo es el máximo (1,e)."],"distractorEvidence":["Invierte los cambios de signo.","Pierde el signo negativo al evaluar f(−3/2).","Omite el mínimo relativo."],"solutionSteps":["La tabla de signos de f′ cambia de − a + en x=−3/2: allí hay un mínimo relativo.","Evaluamos f(−3/2)=(−9)e^(−3/2).","La tabla cambia de + a − en x=1: allí hay un máximo relativo, y f(1)=e.","Los puntos extremos son (−3/2,−9e^(−3/2)) y (1,e)."],"finalAnswer":"Mínimo (−3/2,−9e^(−3/2)); máximo (1,e).","verification":{"verified":true,"method":"Cambios de signo de f′ y evaluación exacta"}}],"pau-user-and-9d256a6d008e07c0f8f7267b7cc8":[{"id":"pau-user-and-9d256a6d008e07c0f8f7267b7cc8:a","label":"a)","text":"Esboza la gráfica de g.","semanticAnswer":"g(x)=x(x−2)²/4: corta en x=0 y es tangente al eje OX en x=2; máximo relativo (2/3,8/27) y mínimo relativo (2,0).","distractors":["Corta al eje OX en x=0 y x=2, ambos cruces simples.","Tiene mínimo en (2/3,8/27) y máximo en (2,0).","No corta al eje OX y es siempre positiva."],"distractorEvidence":["Ignora que x=2 es una raíz doble.","Invierte la tabla de signos de g′.","Omite la raíz x=0."],"solutionSteps":["Factorizamos g(x)=x³/4−x²+x=x(x−2)²/4; sus ceros son x=0 y x=2, este último doble.","g′(x)=3x²/4−2x+1=(3x−2)(x−2)/4. Sus puntos críticos son x=2/3 y x=2.","Recta de signos de g′: positiva, negativa y positiva; por ello hay máximo en (2/3,8/27) y mínimo en (2,0).","Con coeficiente principal positivo, g tiende a −∞ a la izquierda y a +∞ a la derecha; cruza en 0 y toca el eje en 2."],"finalAnswer":"Cúbica que cruza en (0,0), alcanza (2/3,8/27) y toca el eje en (2,0).","verification":{"verified":true,"method":"Factorización, signos de g′ y comportamiento asintótico"}},{"id":"pau-user-and-9d256a6d008e07c0f8f7267b7cc8:b","label":"b)","text":"Determina la ecuación de la recta tangente a la gráfica de g en el punto de abscisa x=2.","semanticAnswer":"La recta tangente es y=0.","distractors":["y=x−2.","y=2x−4.","y=−x+2."],"distractorEvidence":["Usa pendiente 1.","Usa pendiente 2.","Usa pendiente −1."],"solutionSteps":["Calculamos g(2)=0.","La derivada es g′(x)=3x²/4−2x+1.","Evaluamos g′(2)=3−4+1=0.","La tangente es y−0=0·(x−2), es decir, y=0."],"finalAnswer":"y=0.","verification":{"verified":true,"method":"Ecuación punto-pendiente"}},{"id":"pau-user-and-9d256a6d008e07c0f8f7267b7cc8:c","label":"c)","text":"Calcula el área del recinto limitado por la gráfica de g y el eje de abscisas.","semanticAnswer":"El área encerrada entre x=0 y x=2 es 1/3 unidad cuadrada.","distractors":["El área es 0.","El área es 2/3.","El área es 4/3."],"distractorEvidence":["Confunde integral orientada con área sin calcular.","Duplica el valor correcto.","Multiplica por cuatro el valor correcto."],"solutionSteps":["Los cortes con OX son x=0 y x=2. Como g(x)=x(x−2)²/4≥0 en [0,2], la curva es el techo y y=0 el suelo.","El recinto se representa entre los puntos (0,0) y (2,0), bajo la curva, que alcanza el máximo local (2/3,8/27).","Calculamos A=∫₀²(x³/4−x²+x)dx=[x⁴/16−x³/3+x²/2]₀².","A=1−8/3+2=1/3>0 unidad cuadrada."],"solutionMathOptions":{"solutionGraph":{"src":"data:image/svg+xml;base64,","alt":"Recinto cartesiano entre g(x) y el eje OX, con cortes, techo, suelo y región sombreada"}},"finalAnswer":"A=1/3 unidad cuadrada.","verification":{"verified":true,"method":"Puntos de corte, signo del integrando y regla de Barrow"}}],"pau-can-ex-1cb12958ea6097466563429ebaa9268f":[{"id":"pau-can-ex-1cb12958ea6097466563429ebaa9268f:a-i","label":"a.i)","text":"Practique deporte y no estudie idiomas.","semanticAnswer":"P(D∩Iᶜ)=0,40.","canonicalSemanticAnswer":"P(D∩Iᶜ)=0,40.","distractors":["P(D∩Iᶜ)=0,35.","P(D∩Iᶜ)=0,60.","P(D∩Iᶜ)=0,45."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Datos: P(D∪I)=0,80, P(D∩I)=0,35 y P(Iᶜ)=0,60; luego P(I)=0,40.","Por inclusión-exclusión, P(D)=0,80−0,40+0,35=0,75.","Restamos la intersección: P(D∩Iᶜ)=P(D)−P(D∩I)=0,75−0,35=0,40.","Comprobación: 0,40+0,35+0,05+0,20=1."],"finalAnswer":"P(D∩Iᶜ)=0,40.","canonicalFinalAnswer":"P(D∩Iᶜ)=0,40.","verification":{"verified":true,"method":"INCLUSION_EXCLUSION_PARTITION","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-1cb12958ea6097466563429ebaa9268f:a-ii","label":"a.ii)","text":"Estudie idiomas y no practique deporte.","semanticAnswer":"P(I∩Dᶜ)=0,05.","canonicalSemanticAnswer":"P(I∩Dᶜ)=0,05.","distractors":["P(I∩Dᶜ)=0,35.","P(I∩Dᶜ)=0,40.","P(I∩Dᶜ)=0,20."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Como P(Iᶜ)=0,60, se tiene P(I)=0,40.","La parte común es P(D∩I)=0,35.","Por tanto P(I∩Dᶜ)=P(I)−P(D∩I)=0,40−0,35=0,05.","El valor es coherente con la partición completa del espacio muestral."],"finalAnswer":"P(I∩Dᶜ)=0,05.","canonicalFinalAnswer":"P(I∩Dᶜ)=0,05.","verification":{"verified":true,"method":"EVENT_DIFFERENCE","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-1cb12958ea6097466563429ebaa9268f:a-iii","label":"a.iii)","text":"Haga solamente una de las dos actividades.","semanticAnswer":"P(solo una)=0,45.","canonicalSemanticAnswer":"P(solo una)=0,45.","distractors":["P(solo una)=0,80.","P(solo una)=0,35.","P(solo una)=0,55."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Hacer solo una actividad reúne los sucesos disjuntos D∩Iᶜ e I∩Dᶜ.","Ya se obtuvo P(D∩Iᶜ)=0,40.","También P(I∩Dᶜ)=0,05.","Sumamos: P(solo una)=0,40+0,05=0,45."],"finalAnswer":"P(solo una)=0,45.","canonicalFinalAnswer":"P(solo una)=0,45.","verification":{"verified":true,"method":"DISJOINT_UNION","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-1cb12958ea6097466563429ebaa9268f:a-iv","label":"a.iv)","text":"No haga ninguna de las dos actividades.","semanticAnswer":"P(ninguna)=0,20.","canonicalSemanticAnswer":"P(ninguna)=0,20.","distractors":["P(ninguna)=0,80.","P(ninguna)=0,35.","P(ninguna)=0,45."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["El suceso «ninguna» es el complementario de D∪I.","El enunciado da P(D∪I)=0,80.","Aplicamos la regla del complementario: P((D∪I)ᶜ)=1−0,80=0,20.","La suma de las cuatro regiones de la partición vale 1."],"finalAnswer":"P(ninguna)=0,20.","canonicalFinalAnswer":"P(ninguna)=0,20.","verification":{"verified":true,"method":"COMPLEMENT_RULE","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-1cb12958ea6097466563429ebaa9268f:b","label":"b)","text":"¿Son independientes los sucesos “Practicar deporte” y “Estudiar idiomas”?","semanticAnswer":"No son independientes.","canonicalSemanticAnswer":"No son independientes.","distractors":["Sí, porque P(D∩I)=0,35.","Sí, porque P(D∪I)=0,80.","No se puede decidir con los datos dados."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Para que fueran independientes debería cumplirse P(D∩I)=P(D)·P(I).","Tenemos P(D)=0,75 y P(I)=0,40.","El producto es 0,75·0,40=0,30.","Como 0,35≠0,30, los sucesos no son independientes."],"finalAnswer":"No son independientes.","canonicalFinalAnswer":"No son independientes.","verification":{"verified":true,"method":"INDEPENDENCE_IDENTITY","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}}],"pau-can-ex-9a61afb3df4a398a5226085474d60215":[{"id":"pau-can-ex-9a61afb3df4a398a5226085474d60215:a-i","label":"a.i)","text":"Tenga un ordenador o una tablet.","semanticAnswer":"P(O∪T)=0,90.","canonicalSemanticAnswer":"P(O∪T)=0,90.","distractors":["P(O∪T)=0,70.","P(O∪T)=1,10.","P(O∪T)=0,20."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Datos: P(O)=0,60, P(T)=0,50 y P(O∩T)=0,20.","Aplicamos inclusión-exclusión.","P(O∪T)=0,60+0,50−0,20=0,90.","El complementario, no tener ninguno, vale 0,10."],"finalAnswer":"P(O∪T)=0,90.","canonicalFinalAnswer":"P(O∪T)=0,90.","verification":{"verified":true,"method":"INCLUSION_EXCLUSION","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-9a61afb3df4a398a5226085474d60215:a-ii","label":"a.ii)","text":"No tenga tablet si no tiene ordenador.","semanticAnswer":"P(Tᶜ|Oᶜ)=0,25.","canonicalSemanticAnswer":"P(Tᶜ|Oᶜ)=0,25.","distractors":["P(Tᶜ|Oᶜ)=0,10.","P(Tᶜ|Oᶜ)=0,40.","P(Tᶜ|Oᶜ)=0,75."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["La probabilidad condicionante es P(Oᶜ)=1−0,60=0,40.","No tener ninguno es el complementario de O∪T: P(Oᶜ∩Tᶜ)=0,10.","Por definición, P(Tᶜ|Oᶜ)=P(Oᶜ∩Tᶜ)/P(Oᶜ).","Dividimos: 0,10/0,40=0,25."],"finalAnswer":"P(Tᶜ|Oᶜ)=0,25.","canonicalFinalAnswer":"P(Tᶜ|Oᶜ)=0,25.","verification":{"verified":true,"method":"CONDITIONAL_PROBABILITY","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-9a61afb3df4a398a5226085474d60215:a-iii","label":"a.iii)","text":"Tenga ordenador y no tenga tablet.","semanticAnswer":"P(O∩Tᶜ)=0,40.","canonicalSemanticAnswer":"P(O∩Tᶜ)=0,40.","distractors":["P(O∩Tᶜ)=0,20.","P(O∩Tᶜ)=0,60.","P(O∩Tᶜ)=0,10."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Descomponemos O en dos regiones disjuntas: O∩T y O∩Tᶜ.","P(O)=0,60 y P(O∩T)=0,20.","Restamos: P(O∩Tᶜ)=0,60−0,20=0,40.","La tabla completa suma 0,20+0,40+0,30+0,10=1."],"finalAnswer":"P(O∩Tᶜ)=0,40.","canonicalFinalAnswer":"P(O∩Tᶜ)=0,40.","verification":{"verified":true,"method":"EVENT_DIFFERENCE","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-9a61afb3df4a398a5226085474d60215:b","label":"b)","text":"¿Son incompatibles? ¿Son independientes los sucesos “Tener un ordenador” y “Tener una tablet”?","semanticAnswer":"No son incompatibles y tampoco son independientes.","canonicalSemanticAnswer":"No son incompatibles y tampoco son independientes.","distractors":["Son incompatibles e independientes.","No son incompatibles, pero sí independientes.","Son incompatibles, pero no independientes."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["No son incompatibles porque P(O∩T)=0,20>0.","Para independencia comparamos P(O∩T) con P(O)·P(T).","P(O)·P(T)=0,60·0,50=0,30.","Como 0,20≠0,30, tampoco son independientes."],"finalAnswer":"No son incompatibles y tampoco son independientes.","canonicalFinalAnswer":"No son incompatibles y tampoco son independientes.","verification":{"verified":true,"method":"COMPATIBILITY_AND_INDEPENDENCE","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}}],"pau-can-ex-b721fb476a8920483e37adb81674c838":[{"id":"pau-can-ex-b721fb476a8920483e37adb81674c838:a-i","label":"a.i)","text":"Alguno de estos dos medios de pago.","semanticAnswer":"P(T∪M)=0,90.","canonicalSemanticAnswer":"P(T∪M)=0,90.","distractors":["P(T∪M)=0,10.","P(T∪M)=0,80.","P(T∪M)=1,00."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["No admitir ninguno tiene probabilidad 0,10.","Admitir alguno es el suceso complementario.","P(T∪M)=1−0,10=0,90.","El resultado está entre las probabilidades marginales y 1."],"finalAnswer":"P(T∪M)=0,90.","canonicalFinalAnswer":"P(T∪M)=0,90.","verification":{"verified":true,"method":"COMPLEMENT_RULE","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-b721fb476a8920483e37adb81674c838:a-ii","label":"a.ii)","text":"Pagar con móvil sabiendo que admite pagar con tarjeta de crédito.","semanticAnswer":"P(M|T)=0,50.","canonicalSemanticAnswer":"P(M|T)=0,50.","distractors":["P(M|T)=0,40.","P(M|T)=0,625.","P(M|T)=0,90."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["Por inclusión-exclusión, P(T∩M)=0,80+0,50−0,90=0,40.","La probabilidad condicionante es P(T)=0,80.","P(M|T)=P(M∩T)/P(T)=0,40/0,80.","Por tanto P(M|T)=0,50."],"finalAnswer":"P(M|T)=0,50.","canonicalFinalAnswer":"P(M|T)=0,50.","verification":{"verified":true,"method":"CONDITIONAL_PROBABILITY","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}},{"id":"pau-can-ex-b721fb476a8920483e37adb81674c838:b","label":"b)","text":"¿Son independientes los sucesos “Pagar con tarjeta” y “Pagar con móvil”?","semanticAnswer":"Sí, son independientes.","canonicalSemanticAnswer":"Sí, son independientes.","distractors":["No, porque P(T∩M)=0,40.","No, porque P(T∪M)=0,90.","No se puede decidir sin conocer el número de restaurantes."],"distractorEvidence":["Confunde una intersección con una unión o con su complementario.","Omite la condición o divide por una probabilidad distinta de la condicionante.","Introduce una hipótesis de equiprobabilidad o independencia que el enunciado no permite."],"solutionSteps":["La intersección obtenida es P(T∩M)=0,40.","El producto de las marginales vale P(T)·P(M)=0,80·0,50=0,40.","Como ambos valores coinciden, se cumple la condición de independencia.","También P(M|T)=P(M)=0,50, que lo confirma."],"finalAnswer":"Sí, son independientes.","canonicalFinalAnswer":"Sí, son independientes.","verification":{"verified":true,"method":"INDEPENDENCE_IDENTITY","detail":"Resultado comprobado por identidades de sucesos y suma de probabilidades."}}],"pau-user-and-a2399d7ce20cc304ff589d5743a8":[{"id":"pau-user-and-a2399d7ce20cc304ff589d5743a8:a","label":"a)","text":"Determine la monotonía y la curvatura de f.","semanticAnswer":"Crece en (−∞,0)∪(2,+∞), decrece en (0,2); es cóncava hacia abajo en (−∞,1) y hacia arriba en (1,+∞).","canonicalSemanticAnswer":"Crece en (−∞,0)∪(2,+∞), decrece en (0,2); es cóncava hacia abajo en (−∞,1) y hacia arriba en (1,+∞).","distractors":["Invierte todos los intervalos.","Sitúa los cambios en x=−1 y x=1.","Afirma que la función es siempre creciente y convexa."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["f′(x)=3x²−6x=3x(x−2); sus ceros son 0 y 2.","Recta real de signos de f′: + en (−∞,0), − en (0,2) y + en (2,+∞).","f′′(x)=6x−6; recta real de signos de f′′: − si x<1 y + si x>1.","Por tanto el cambio de concavidad se produce en x=1."],"finalAnswer":"Crece en (−∞,0)∪(2,+∞), decrece en (0,2); es cóncava hacia abajo en (−∞,1) y hacia arriba en (1,+∞).","canonicalFinalAnswer":"Crece en (−∞,0)∪(2,+∞), decrece en (0,2); es cóncava hacia abajo en (−∞,1) y hacia arriba en (1,+∞).","verification":{"verified":true,"method":"DERIVATIVE_SIGN_TABLES","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-a2399d7ce20cc304ff589d5743a8:b","label":"b)","text":"Determine los puntos donde la función alcanza sus extremos relativos.","semanticAnswer":"Máximo relativo en (0,4) y mínimo relativo en (2,0).","canonicalSemanticAnswer":"Máximo relativo en (0,4) y mínimo relativo en (2,0).","distractors":["Mínimo en (0,4) y máximo en (2,0).","Máximo en (1,2) y mínimo en (2,0).","No tiene extremos relativos."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Los puntos críticos son x=0 y x=2.","La recta de signos de f′ cambia de + a − en x=0: hay máximo.","Cambia de − a + en x=2: hay mínimo.","Evaluamos f(0)=4 y f(2)=0."],"finalAnswer":"Máximo relativo en (0,4) y mínimo relativo en (2,0).","canonicalFinalAnswer":"Máximo relativo en (0,4) y mínimo relativo en (2,0).","verification":{"verified":true,"method":"EXTREMA_SIGN_CHANGE","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-a2399d7ce20cc304ff589d5743a8:c","label":"c)","text":"Determine la recta tangente a f en x=−1.","semanticAnswer":"y=9x+9.","canonicalSemanticAnswer":"y=9x+9.","distractors":["y=−9x−9.","y=9x.","y=x+1."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["f(−1)=4−3−1=0.","f′(x)=3x²−6x.","La pendiente es f′(−1)=3+6=9.","La ecuación punto-pendiente es y−0=9(x+1), es decir, y=9x+9."],"finalAnswer":"y=9x+9.","canonicalFinalAnswer":"y=9x+9.","verification":{"verified":true,"method":"TANGENT_POINT_SLOPE","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-eb0dd390d6f48d86d0d3793419de":[{"id":"pau-user-and-eb0dd390d6f48d86d0d3793419de:a","label":"a)","text":"Calcule el gasto a partir del cual la empresa no obtiene beneficios.","semanticAnswer":"A partir de x=45 miles de euros el beneficio es no positivo.","canonicalSemanticAnswer":"A partir de x=45 miles de euros el beneficio es no positivo.","distractors":["A partir de x=20.","A partir de x=5.","Nunca deja de obtener beneficio."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Resolvemos B(x)=−3x²+120x+675=0.","Dividimos por −3: x²−40x−225=0.","Las raíces son x=(40±50)/2, es decir, x=−5 y x=45.","Como x≥0 y la parábola abre hacia abajo, B(x)≤0 para x≥45."],"finalAnswer":"A partir de x=45 miles de euros el beneficio es no positivo.","canonicalFinalAnswer":"A partir de x=45 miles de euros el beneficio es no positivo.","verification":{"verified":true,"method":"ROOTS_AND_SIGN","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-eb0dd390d6f48d86d0d3793419de:b","label":"b)","text":"Calcule el valor de x que produce máximo beneficio y dicho beneficio.","semanticAnswer":"El máximo se alcanza en x=20 y vale 1875 miles de euros.","canonicalSemanticAnswer":"El máximo se alcanza en x=20 y vale 1875 miles de euros.","distractors":["x=45 y 0 miles.","x=20 y 675 miles.","x=40 y 1875 miles."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["La parábola abre hacia abajo porque su coeficiente cuadrático es −3.","La abscisa del vértice es x=−120/(2·(−3))=20.","B(20)=−3·400+120·20+675=1875.","Por tanto el vértice (20,1875) es el máximo."],"finalAnswer":"El máximo se alcanza en x=20 y vale 1875 miles de euros.","canonicalFinalAnswer":"El máximo se alcanza en x=20 y vale 1875 miles de euros.","verification":{"verified":true,"method":"PARABOLA_VERTEX","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-eb0dd390d6f48d86d0d3793419de:c","label":"c)","text":"Determine los intervalos de crecimiento y decrecimiento del beneficio.","semanticAnswer":"Crece en [0,20) y decrece en (20,+∞).","canonicalSemanticAnswer":"Crece en [0,20) y decrece en (20,+∞).","distractors":["Decrece en [0,20) y crece después.","Crece en todo su dominio.","Decrece en todo su dominio."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["B′(x)=−6x+120.","El único punto crítico del dominio es x=20.","Recta real de signos de B′: positiva para 0≤x<20, cero en 20 y negativa para x>20.","Así se obtienen los intervalos indicados."],"finalAnswer":"Crece en [0,20) y decrece en (20,+∞).","canonicalFinalAnswer":"Crece en [0,20) y decrece en (20,+∞).","verification":{"verified":true,"method":"FIRST_DERIVATIVE_SIGN_LINE","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-eb0dd390d6f48d86d0d3793419de:d","label":"d)","text":"Represente gráficamente la función B en su dominio x≥0.","semanticAnswer":"Parábola cóncava hacia abajo que pasa por (0,675), tiene vértice (20,1875) y corta OX en (45,0).","canonicalSemanticAnswer":"Parábola cóncava hacia abajo que pasa por (0,675), tiene vértice (20,1875) y corta OX en (45,0).","distractors":["Parábola hacia arriba con vértice (20,1875).","Recta que une (0,675) y (45,0).","Parábola con vértice (45,0)."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["La gráfica es una parábola abierta hacia abajo.","En el dominio comienza en B(0)=675.","Su máximo es el vértice (20,1875).","La raíz válida es x=45; se representa solo el tramo x≥0."],"finalAnswer":"Parábola cóncava hacia abajo que pasa por (0,675), tiene vértice (20,1875) y corta OX en (45,0).","canonicalFinalAnswer":"Parábola cóncava hacia abajo que pasa por (0,675), tiene vértice (20,1875) y corta OX en (45,0).","verification":{"verified":true,"method":"KEY_POINTS_GRAPH","detail":"Resultado sustituido o comprobado de forma independiente."},"solutionMathOptions":{"solutionGraph":{"src":"data:image/svg+xml;base64,","alt":"Gráfica de B con ordenada en el origen, vértice y corte con OX"}}}],"pau-user-and-2d24fc052b2f090732a36320d027":[{"id":"pau-user-and-2d24fc052b2f090732a36320d027:a","label":"a)","text":"Dadas F=(2,−1,3) y C=(1,5,−2)ᵀ, calcule C·F y F·C.","semanticAnswer":"C·F=[[2,−1,3],[10,−5,15],[−4,2,−6]] y F·C=−9.","canonicalSemanticAnswer":"C·F=[[2,−1,3],[10,−5,15],[−4,2,−6]] y F·C=−9.","distractors":["C·F=−9 y F·C es la matriz 3×3.","C·F=[[2,−1,3],[5,−5,15],[−4,2,−6]] y F·C=9.","Ambos productos valen −9."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["C es 3×1 y F es 1×3; por tanto C·F es 3×3.","Multiplicamos cada entrada de C por la fila F y obtenemos [[2,−1,3],[10,−5,15],[−4,2,−6]].","F·C es 1×1: 2·1+(−1)·5+3·(−2).","La suma es 2−5−6=−9."],"finalAnswer":"C·F=[[2,−1,3],[10,−5,15],[−4,2,−6]] y F·C=−9.","canonicalFinalAnswer":"C·F=[[2,−1,3],[10,−5,15],[−4,2,−6]] y F·C=−9.","verification":{"verified":true,"method":"MATRIX_DIMENSIONS_AND_PRODUCTS","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-2d24fc052b2f090732a36320d027:b","label":"b)","text":"Con A=[[2,0],[1,−1]], B=[[1,−3],[2,−1]] y C=[[1,−1],[−1,0]], calcule X si X·A⁻¹−B=C.","semanticAnswer":"X=[[0,4],[1,1]].","canonicalSemanticAnswer":"X=[[0,4],[1,1]].","distractors":["X=[[2,−4],[1,−1]].","X=[[4,0],[1,1]].","X=[[0,−4],[−1,1]]."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Aislamos X·A⁻¹=B+C.","Sumamos B+C=[[2,−4],[1,−1]].","Multiplicamos por A a la derecha: X=(B+C)A.","El producto [[2,−4],[1,−1]][[2,0],[1,−1]]=[[0,4],[1,1]]; al sustituir se recupera B+C."],"finalAnswer":"X=[[0,4],[1,1]].","canonicalFinalAnswer":"X=[[0,4],[1,1]].","verification":{"verified":true,"method":"MATRIX_EQUATION_SUBSTITUTION","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-811c534e78c560165a5ca0d0ea4f":[{"id":"pau-user-and-811c534e78c560165a5ca0d0ea4f:a","label":"a)","text":"Con A=[[1,2],[0,1]] y B=[[0,−1],[2,4]], calcule (A+B)(A−B).","semanticAnswer":"(A+B)(A−B)=[[−1,0],[−8,−9]].","canonicalSemanticAnswer":"(A+B)(A−B)=[[−1,0],[−8,−9]].","distractors":["[[−1,0],[−8,9]].","[[1,0],[8,−9]].","A²−B²."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["A+B=[[1,1],[2,5]].","A−B=[[1,3],[−2,−3]].","Multiplicamos fila por columna.","El resultado es [[1−2,3−3],[2−10,6−15]]=[[−1,0],[−8,−9]]."],"finalAnswer":"(A+B)(A−B)=[[−1,0],[−8,−9]].","canonicalFinalAnswer":"(A+B)(A−B)=[[−1,0],[−8,−9]].","verification":{"verified":true,"method":"DIRECT_MATRIX_PRODUCT","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-811c534e78c560165a5ca0d0ea4f:b","label":"b)","text":"Determine X en (A+2B)X=3I₂.","semanticAnswer":"X=[[3,0],[−4/3,1/3]].","canonicalSemanticAnswer":"X=[[3,0],[−4/3,1/3]].","distractors":["X=[[3,0],[4/3,1/3]].","X=[[1,0],[−4/9,1/9]].","X=[[3,0],[−4/3,3]]."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["A+2B=[[1,0],[4,9]].","Su determinante es 9. Por adjunta: adj(A+2B)=[[9,0],[−4,1]].","(A+2B)⁻¹=(1/9)[[9,0],[−4,1]].","X=3(A+2B)⁻¹=[[3,0],[−4/3,1/3]]; el producto con A+2B es 3I₂."],"finalAnswer":"X=[[3,0],[−4/3,1/3]].","canonicalFinalAnswer":"X=[[3,0],[−4/3,1/3]].","verification":{"verified":true,"method":"ADJUGATE_INVERSE_AND_SUBSTITUTION","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-c3ab9ccf5d57298c1a9824964739":[{"id":"pau-user-and-c3ab9ccf5d57298c1a9824964739:a","label":"a)","text":"Despeje la matriz X en A·X+B=A, sabiendo que A tiene inversa.","semanticAnswer":"X=A⁻¹(A−B).","canonicalSemanticAnswer":"X=A⁻¹(A−B).","distractors":["X=(A−B)A⁻¹.","X=A⁻¹(A+B).","X=A−B."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Restamos B en ambos miembros: A·X=A−B.","Multiplicamos a la izquierda por A⁻¹, pues A⁻¹A=I.","Resulta X=A⁻¹(A−B); el orden no puede intercambiarse porque el producto matricial no es conmutativo.","Comprobación: A·A⁻¹(A−B)+B=A−B+B=A."],"finalAnswer":"X=A⁻¹(A−B).","canonicalFinalAnswer":"X=A⁻¹(A−B).","verification":{"verified":true,"method":"MATRIX_EQUATION_ISOLATION","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-c3ab9ccf5d57298c1a9824964739:b","label":"b)","text":"Obtenga X para A=[[2,5],[1,3]] y B=[[0,−3],[−1,2]].","semanticAnswer":"X=[[-4,19],[2,−6]].","canonicalSemanticAnswer":"X=[[-4,19],[2,−6]].","distractors":["X=[[-4,2],[19,−6]].","X=[[4,−19],[−2,6]].","X=[[2,8],[2,1]]."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["det(A)=2·3−5·1=1. La matriz de cofactores es [[3,−1],[−5,2]] y adj(A)=[[3,−5],[−1,2]].","Por el procedimiento de la adjunta, A⁻¹=(1/det(A))·adj(A)=[[3,−5],[−1,2]].","A−B=[[2,8],[2,1]] y X=A⁻¹(A−B).","Multiplicando fila por columna obtenemos X=[[-4,19],[2,−6]]; la sustitución verifica A·X+B=A."],"finalAnswer":"X=[[-4,19],[2,−6]].","canonicalFinalAnswer":"X=[[-4,19],[2,−6]].","verification":{"verified":true,"method":"ADJUGATE_INVERSE_AND_MATRIX_EQUATION","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-57ce8292ea6366f4ec4b18f32f84":[{"id":"pau-user-and-57ce8292ea6366f4ec4b18f32f84:a","label":"a)","text":"¿Es f continua en x=0? ¿Es continua en su dominio?","semanticAnswer":"Sí, es continua en x=0 y en todo ℝ.","canonicalSemanticAnswer":"Sí, es continua en x=0 y en todo ℝ.","distractors":["No es continua en x=0.","Solo es continua para x>0.","Es continua salvo en x=1."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["La rama izquierda es e^(−x) para x≤0 y la derecha x³−x+1 para x>0.","f(0)=e⁰=1 y lim(x→0⁻)e^(−x)=1.","lim(x→0⁺)(x³−x+1)=1.","Los dos límites coinciden con f(0); como cada rama es continua en su intervalo, f es continua en ℝ."],"finalAnswer":"Sí, es continua en x=0 y en todo ℝ.","canonicalFinalAnswer":"Sí, es continua en x=0 y en todo ℝ.","verification":{"verified":true,"method":"ONE_SIDED_CONTINUITY","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-57ce8292ea6366f4ec4b18f32f84:b","label":"b)","text":"¿Es f derivable en x=0? ¿Es derivable en su dominio?","semanticAnswer":"Sí, es derivable en x=0 y en todo ℝ.","canonicalSemanticAnswer":"Sí, es derivable en x=0 y en todo ℝ.","distractors":["No es derivable en x=0.","Solo es derivable para x<0.","Es derivable salvo en x=1."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Para x<0, f′(x)=−e^(−x); por tanto f′(0⁻)=−1.","Para x>0, f′(x)=3x²−1; por tanto f′(0⁺)=−1.","Las derivadas laterales coinciden y f es continua en 0, luego es derivable allí.","Cada rama es derivable en el interior de su intervalo; por tanto f es derivable en ℝ."],"finalAnswer":"Sí, es derivable en x=0 y en todo ℝ.","canonicalFinalAnswer":"Sí, es derivable en x=0 y en todo ℝ.","verification":{"verified":true,"method":"ONE_SIDED_DERIVATIVES","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-57ce8292ea6366f4ec4b18f32f84:c","label":"c)","text":"Halle la ecuación de la recta tangente a la gráfica de f en x=1.","semanticAnswer":"y=2x−1.","canonicalSemanticAnswer":"y=2x−1.","distractors":["y=2x+1.","y=x.","y=−2x+3."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Como 1>0 usamos f(x)=x³−x+1.","f(1)=1 y f′(x)=3x²−1, de modo que f′(1)=2.","Aplicamos la ecuación punto-pendiente: y−1=2(x−1).","Simplificando, la tangente es y=2x−1."],"finalAnswer":"y=2x−1.","canonicalFinalAnswer":"y=2x−1.","verification":{"verified":true,"method":"TANGENT_POINT_SLOPE","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-8e53f9bc10323ec27c44d77c9c59":[{"id":"pau-user-and-8e53f9bc10323ec27c44d77c9c59:a","label":"a)","text":"Esboza la gráfica de g(x)=2x+|x²−1|.","semanticAnswer":"g(x)=x²+2x−1 si x<−1 o x>1, y g(x)=−x²+2x+1 si −1≤x≤1.","canonicalSemanticAnswer":"g(x)=x²+2x−1 si x<−1 o x>1, y g(x)=−x²+2x+1 si −1≤x≤1.","distractors":["Se usa la misma parábola en todo ℝ.","Se cambia el signo de 2x.","Las ramas se intercambian."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Resolvemos x²−1=0: los puntos de cambio son x=−1 y x=1.","Si |x|≥1, |x²−1|=x²−1 y g=x²+2x−1.","Si |x|≤1, |x²−1|=1−x² y g=−x²+2x+1.","Las ramas coinciden en g(−1)=−2 y g(1)=2, lo que permite trazar una gráfica continua."],"finalAnswer":"g(x)=x²+2x−1 si x<−1 o x>1, y g(x)=−x²+2x+1 si −1≤x≤1.","canonicalFinalAnswer":"g(x)=x²+2x−1 si x<−1 o x>1, y g(x)=−x²+2x+1 si −1≤x≤1.","verification":{"verified":true,"method":"ABSOLUTE_VALUE_PIECEWISE","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-8e53f9bc10323ec27c44d77c9c59:b","label":"b)","text":"Calcula ∫₀² g(x) dx.","semanticAnswer":"∫₀²g(x)dx=6.","canonicalSemanticAnswer":"∫₀²g(x)dx=6.","distractors":["∫₀²g(x)dx=5.","∫₀²g(x)dx=13/3.","∫₀²g(x)dx=18."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["El valor absoluto cambia en x=1 dentro de [0,2].","Separamos ∫₀¹(−x²+2x+1)dx+∫₁²(x²+2x−1)dx.","La primera integral vale 5/3 y la segunda 13/3.","Sumamos 5/3+13/3=18/3=6."],"finalAnswer":"∫₀²g(x)dx=6.","canonicalFinalAnswer":"∫₀²g(x)dx=6.","verification":{"verified":true,"method":"PIECEWISE_DEFINITE_INTEGRAL","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-a1727ad9477ebef1f54383f9448a":[{"id":"pau-user-and-a1727ad9477ebef1f54383f9448a:a","label":"a)","text":"Esboza las gráficas de f(x)=x²−1 y g(x)=2x+2.","semanticAnswer":"La parábola y la recta se cortan en (−1,0) y (3,8); la recta queda por encima entre ambos puntos.","canonicalSemanticAnswer":"La parábola y la recta se cortan en (−1,0) y (3,8); la recta queda por encima entre ambos puntos.","distractors":["Se cortan en x=−3 y x=1.","Solo se cortan en (1,4).","La parábola queda por encima entre los cortes."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Igualamos x²−1=2x+2.","Obtenemos x²−2x−3=(x+1)(x−3)=0.","Los cortes son (−1,0) y (3,8).","En x=0, g(0)=2>f(0)=−1, por lo que la recta es el techo del recinto."],"finalAnswer":"La parábola y la recta se cortan en (−1,0) y (3,8); la recta queda por encima entre ambos puntos.","canonicalFinalAnswer":"La parábola y la recta se cortan en (−1,0) y (3,8); la recta queda por encima entre ambos puntos.","verification":{"verified":true,"method":"INTERSECTIONS_AND_GRAPH","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-a1727ad9477ebef1f54383f9448a:b","label":"b)","text":"Calcula el área del recinto limitado por las gráficas de f y g.","semanticAnswer":"A=32/3 unidades cuadradas.","canonicalSemanticAnswer":"A=32/3 unidades cuadradas.","distractors":["A=16/3.","A=32.","A=−32/3."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Los puntos de corte son x=−1 y x=3; en ese intervalo el techo es g y el suelo f.","A=∫₋₁³[(2x+2)−(x²−1)]dx=∫₋₁³(−x²+2x+3)dx.","Una primitiva es −x³/3+x²+3x.","Aplicando Barrow resulta A=32/3>0 unidades cuadradas."],"finalAnswer":"A=32/3 unidades cuadradas.","canonicalFinalAnswer":"A=32/3 unidades cuadradas.","verification":{"verified":true,"method":"AREA_BETWEEN_CURVES","detail":"Resultado sustituido o comprobado de forma independiente."},"solutionMathOptions":{"solutionGraph":{"src":"data:image/svg+xml;base64,","alt":"Recinto entre la recta y la parábola con cortes x=-1 y x=3"}}}],"pau-user-and-62576c262aaef19175cb1ced51a7":[{"id":"pau-user-and-62576c262aaef19175cb1ced51a7:a","label":"a)","text":"Estudia la continuidad y derivabilidad de f(x)=1/(x−1) si x<0 y f(x)=x²−3x−1 si x≥0.","semanticAnswer":"Es continua en ℝ, pero no es derivable en x=0; sí lo es en ℝ∖{0}.","canonicalSemanticAnswer":"Es continua en ℝ, pero no es derivable en x=0; sí lo es en ℝ∖{0}.","distractors":["No es continua en x=0.","Es derivable en todo ℝ.","Tiene una discontinuidad en x=1."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["En x=0, f(0)=−1 y lim(x→0⁻)1/(x−1)=−1=lim(x→0⁺)(x²−3x−1).","Por tanto es continua en 0; las ramas son continuas en sus intervalos.","La derivada izquierda en 0 es −1/(x−1)² evaluada en 0: −1.","La derivada derecha es 2x−3 y vale −3 en 0; como no coinciden, no es derivable en 0."],"finalAnswer":"Es continua en ℝ, pero no es derivable en x=0; sí lo es en ℝ∖{0}.","canonicalFinalAnswer":"Es continua en ℝ, pero no es derivable en x=0; sí lo es en ℝ∖{0}.","verification":{"verified":true,"method":"PIECEWISE_CONTINUITY_DERIVABILITY","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-62576c262aaef19175cb1ced51a7:b","label":"b)","text":"Determina las asíntotas y los extremos relativos de f.","semanticAnswer":"Asíntota horizontal y=0 cuando x→−∞; mínimo relativo en (3/2,−13/4).","canonicalSemanticAnswer":"Asíntota horizontal y=0 cuando x→−∞; mínimo relativo en (3/2,−13/4).","distractors":["Asíntota vertical x=1 y máximo en (3/2,−13/4).","Asíntota y=1 y mínimo en (3,−1).","No tiene asíntotas ni extremos."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["En la rama x<0, lim(x→−∞)1/(x−1)=0: la asíntota horizontal es y=0. La posible x=1 no pertenece al intervalo de esa rama.","Para x>0, f′(x)=2x−3 y se anula en x=3/2.","Recta real de signos de f′: negativa antes de 3/2 y positiva después; por ello hay un mínimo.","f(3/2)=9/4−9/2−1=−13/4."],"finalAnswer":"Asíntota horizontal y=0 cuando x→−∞; mínimo relativo en (3/2,−13/4).","canonicalFinalAnswer":"Asíntota horizontal y=0 cuando x→−∞; mínimo relativo en (3/2,−13/4).","verification":{"verified":true,"method":"ASYMPTOTES_AND_FIRST_DERIVATIVE_SIGN_LINE","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-62576c262aaef19175cb1ced51a7:c","label":"c)","text":"Esboza la gráfica de f.","semanticAnswer":"Rama racional negativa para x<0, que se aproxima a y=0 y llega a (0,−1); desde ahí, rama parabólica con mínimo (3/2,−13/4).","canonicalSemanticAnswer":"Rama racional negativa para x<0, que se aproxima a y=0 y llega a (0,−1); desde ahí, rama parabólica con mínimo (3/2,−13/4).","distractors":["Las dos ramas presentan un salto en x=0.","La rama derecha tiene un máximo.","Existe una asíntota vertical x=1."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Para x<0 trazamos 1/(x−1): es negativa, decreciente y se aproxima a y=0 al ir a −∞.","Ambas ramas se unen en el punto (0,−1).","Para x≥0 trazamos la parábola x²−3x−1, abierta hacia arriba.","Marcamos su mínimo (3/2,−13/4) y los cortes calculables para completar el esbozo."],"finalAnswer":"Rama racional negativa para x<0, que se aproxima a y=0 y llega a (0,−1); desde ahí, rama parabólica con mínimo (3/2,−13/4).","canonicalFinalAnswer":"Rama racional negativa para x<0, que se aproxima a y=0 y llega a (0,−1); desde ahí, rama parabólica con mínimo (3/2,−13/4).","verification":{"verified":true,"method":"PIECEWISE_GRAPH","detail":"Resultado sustituido o comprobado de forma independiente."}}],"pau-user-and-c76fee258565f825a79201f9ab07":[{"id":"pau-user-and-c76fee258565f825a79201f9ab07:a","label":"a)","text":"Esboza el recinto limitado por f(x)=|x| y g(x)=6−x².","semanticAnswer":"El recinto es simétrico, con cortes en (−2,2) y (2,2); g es el techo y f el suelo.","canonicalSemanticAnswer":"El recinto es simétrico, con cortes en (−2,2) y (2,2); g es el techo y f el suelo.","distractors":["Los cortes son x=−3 y x=3.","f es el techo entre los cortes.","Solo existe el corte (2,2)."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Por simetría basta estudiar x≥0, donde |x|=x.","Igualamos x=6−x²: x²+x−6=0, y el corte positivo es x=2.","Por simetría aparece también x=−2; ambos puntos tienen ordenada 2.","En [−2,2], 6−x² queda por encima de |x|."],"finalAnswer":"El recinto es simétrico, con cortes en (−2,2) y (2,2); g es el techo y f el suelo.","canonicalFinalAnswer":"El recinto es simétrico, con cortes en (−2,2) y (2,2); g es el techo y f el suelo.","verification":{"verified":true,"method":"ABSOLUTE_VALUE_REGION","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-c76fee258565f825a79201f9ab07:b","label":"b)","text":"Calcula el área del recinto limitado por f y g.","semanticAnswer":"A=44/3 unidades cuadradas.","canonicalSemanticAnswer":"A=44/3 unidades cuadradas.","distractors":["A=22/3.","A=16.","A=−44/3."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["El recinto es simétrico respecto del eje OY.","En [0,2], el techo es 6−x² y el suelo x.","A=2∫₀²(6−x²−x)dx=2[6x−x³/3−x²/2]₀².","A=2(12−8/3−2)=44/3 unidades cuadradas."],"finalAnswer":"A=44/3 unidades cuadradas.","canonicalFinalAnswer":"A=44/3 unidades cuadradas.","verification":{"verified":true,"method":"SYMMETRIC_AREA_BETWEEN_CURVES","detail":"Resultado sustituido o comprobado de forma independiente."},"solutionMathOptions":{"solutionGraph":{"src":"data:image/svg+xml;base64,","alt":"Recinto simétrico entre y=6-x² e y=|x|"}}}],"pau-user-and-93a1681eecb1df2fcb44cab99782":[{"id":"pau-user-and-93a1681eecb1df2fcb44cab99782:a","label":"a)","text":"Determina los intervalos de crecimiento y decrecimiento de f(x)=x+e^(−x), así como sus extremos relativos.","semanticAnswer":"Decrece en (−∞,0), crece en (0,+∞) y tiene un mínimo relativo y absoluto en (0,1).","canonicalSemanticAnswer":"Decrece en (−∞,0), crece en (0,+∞) y tiene un mínimo relativo y absoluto en (0,1).","distractors":["Crece en (−∞,0) y decrece después.","Tiene un máximo en (0,1).","Es creciente en todo ℝ."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["f′(x)=1−e^(−x) y f′(x)=0 equivale a x=0.","Recta real de signos de f′: negativa si x<0, cero en 0 y positiva si x>0.","Por ello f decrece antes de 0 y crece después.","El cambio −|0|+ confirma un mínimo en (0,f(0))=(0,1)."],"finalAnswer":"Decrece en (−∞,0), crece en (0,+∞) y tiene un mínimo relativo y absoluto en (0,1).","canonicalFinalAnswer":"Decrece en (−∞,0), crece en (0,+∞) y tiene un mínimo relativo y absoluto en (0,1).","verification":{"verified":true,"method":"FIRST_DERIVATIVE_SIGN_LINE","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-93a1681eecb1df2fcb44cab99782:b","label":"b)","text":"Determina las asíntotas de la gráfica de f.","semanticAnswer":"La única asíntota es la oblicua y=x cuando x→+∞.","canonicalSemanticAnswer":"La única asíntota es la oblicua y=x cuando x→+∞.","distractors":["La asíntota es y=−x.","Tiene asíntota horizontal y=0.","Tiene asíntota vertical x=0."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["No hay asíntotas verticales porque el dominio es ℝ.","Cuando x→+∞, f(x)−x=e^(−x)→0.","Por tanto y=x es asíntota oblicua a la derecha.","Cuando x→−∞, e^(−x) domina y no existe una recta asintótica."],"finalAnswer":"La única asíntota es la oblicua y=x cuando x→+∞.","canonicalFinalAnswer":"La única asíntota es la oblicua y=x cuando x→+∞.","verification":{"verified":true,"method":"ASYMPTOTE_LIMITS","detail":"Resultado sustituido o comprobado de forma independiente."}},{"id":"pau-user-and-93a1681eecb1df2fcb44cab99782:c","label":"c)","text":"Esboza la gráfica de f.","semanticAnswer":"Gráfica convexa con mínimo (0,1), decreciente antes de 0, creciente después y aproximándose a y=x por arriba cuando x→+∞.","canonicalSemanticAnswer":"Gráfica convexa con mínimo (0,1), decreciente antes de 0, creciente después y aproximándose a y=x por arriba cuando x→+∞.","distractors":["Gráfica cóncava con máximo (0,1).","Recta y=x en todo el dominio.","Gráfica con asíntota vertical x=0."],"distractorEvidence":["Error de signo o de operación.","Omisión de una condición del enunciado.","Aplicación incompleta del procedimiento."],"solutionSteps":["Usamos la monotonía y el mínimo (0,1).","f′′(x)=e^(−x)>0 en ℝ; recta real de signos de f′′: siempre positiva, luego la gráfica es convexa.","Cuando x→−∞ la función tiende a +∞.","Cuando x→+∞ se aproxima por encima a la recta y=x."],"finalAnswer":"Gráfica convexa con mínimo (0,1), decreciente antes de 0, creciente después y aproximándose a y=x por arriba cuando x→+∞.","canonicalFinalAnswer":"Gráfica convexa con mínimo (0,1), decreciente antes de 0, creciente después y aproximándose a y=x por arriba cuando x→+∞.","verification":{"verified":true,"method":"QUALITATIVE_GRAPH","detail":"Resultado sustituido o comprobado de forma independiente."}}]});
